TLM.f("Tempora/Quad1-0",{"officium":"Dominica I in Quadragesima","rule":["no Gloria","Credo","Prefatio=Quad","Suffragium=Sanctorum;Vivis;;"],"sections":{"Introitus":[{"k":"ref","la":"Ps 90:15; 90:16"},{"k":"text","la":"Invocábit me, et ego exáudiam eum: erípiam eum, et glorificábo eum: longitúdine diérum adimplébo eum."},{"k":"ref","la":"Ps 90:1"},{"k":"text","la":"Qui hábitat in adjutório Altíssimi, in protectióne Dei cœli commorábitur."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Invocábit me, et ego exáudiam eum: erípiam eum, et glorificábo eum: longitúdine diérum adimplébo eum."}],"Oratio":[{"k":"text","la":"Deus, qui Ecclésiam tuam ánnua quadragesimáli observatióne puríficas: præsta famíliæ tuæ; ut, quod a te obtinére abstinéndo nítitur, hoc bonis opéribus exsequátur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Corínthios"},{"k":"ref","la":"2 Cor 6:1-10"},{"k":"text","la":"Fratres: Exhortámur vos, ne in vácuum grátiam Dei recipiátis. Ait enim: Témpore accépto exaudívi te, et in die salútis adjúvi te. Ecce, nunc tempus acceptábile, ecce, nunc dies salútis. Némini dantes ullam offensiónem, ut non vituperétur ministérium nostrum: sed in ómnibus exhibeámus nosmetípsos sicut Dei minístros, in multa patiéntia, in tribulatiónibus, in necessitátibus, in angústiis, in plagis, in carcéribus, in seditiónibus, in labóribus, in vigíliis, in jejúniis, in castitáte, in sciéntia, in longanimitáte, in suavitáte, in Spíritu Sancto, in caritáte non ficta, in verbo veritátis, in virtúte Dei, per arma justítiæ a dextris et a sinístris: per glóriam et ignobilitátem: per infámiam et bonam famam: ut seductóres et veráces: sicut qui ignóti et cógniti: quasi moriéntes et ecce, vívimus: ut castigáti et non mortificáti: quasi tristes, semper autem gaudéntes: sicut egéntes, multos autem locupletántes: tamquam nihil habéntes et ómnia possidéntes."}],"Graduale":[{"k":"ref","la":"Ps 90:11-12"},{"k":"text","la":"Angelis suis Deus mandávit de te, ut custódiant te in ómnibus viis tuis."},{"k":"text","la":"In mánibus portábunt te, ne umquam offéndas ad lápidem pedem tuum.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 90:1-7; 90:11-16"},{"k":"text","la":"Qui hábitat in adjutório Altíssimi, in protectióne Dei cœli commorántur."},{"k":"text","la":"Dicet Dómino: Suscéptor meus es tu et refúgium meum: Deus meus, sperábo in eum.","mark":"V"},{"k":"text","la":"Quóniam ipse liberávit me de láqueo venántium et a verbo áspero.","mark":"V"},{"k":"text","la":"Scápulis suis obumbrábit tibi, et sub pennis ejus sperábis.","mark":"V"},{"k":"text","la":"Scuto circúmdabit te véritas ejus: non timébis a timóre noctúrno.","mark":"V"},{"k":"text","la":"A sagítta volánte per diem, a negótio perambulánte in ténebris, a ruína et dæmónio meridiáno.","mark":"V"},{"k":"text","la":"Cadent a látere tuo mille, et decem mília a dextris tuis: tibi autem non appropinquábit.","mark":"V"},{"k":"text","la":"Quóniam Angelis suis mandávit de te, ut custódiant te in ómnibus viis tuis.","mark":"V"},{"k":"text","la":"In mánibus portábunt te, ne umquam offéndas ad lápidem pedem tuum,","mark":"V"},{"k":"text","la":"Super áspidem et basilíscum ambulábis, et conculcábis leónem et dracónem.","mark":"V"},{"k":"text","la":"Quóniam in me sperávit, liberábo eum: prótegam eum, quóniam cognóvit nomen meum,","mark":"V"},{"k":"text","la":"Invocábit me, et ego exáudiam eum: cum ipso sum in tribulatióne,","mark":"V"},{"k":"text","la":"Erípiam eum et glorificábo eum: longitúdine diérum adimplébo eum, et osténdam illi salutáre meum.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 4:1-11"},{"k":"text","la":"In illo témpore: Ductus est Jesus in desértum a Spíritu, ut tentarétur a diábolo. Et cum jejunásset quadragínta diébus et quadragínta nóctibus, postea esúriit. Et accédens tentátor, dixit ei: Si Fílius Dei es, dic, ut lápides isti panes fiant. Qui respóndens, dixit: Scriptum est: Non in solo pane vivit homo, sed in omni verbo, quod procédit de ore Dei. Tunc assúmpsit eum diábolus in sanctam civitátem, et státuit eum super pinnáculum templi, et dixit ei: Si Fílius Dei es, mitte te deórsum. Scriptum est enim: Quia Angelis suis mandávit de te, et in mánibus tollent te, ne forte offéndas ad lápidem pedem tuum. Ait illi Jesus: Rursum scriptum est: Non tentábis Dóminum, Deum tuum. Iterum assúmpsit eum diábolus in montem excélsum valde: et ostendit ei ómnia regna mundi et glóriam eórum, et dixit ei: Hæc ómnia tibi dabo, si cadens adoráveris me. Tunc dicit ei Jesus: Vade, Sátana; scriptum est enim: Dóminum, Deum tuum, adorábis, et illi soli sérvies. Tunc relíquit eum diábolus: et ecce, Angeli accessérunt et ministrábant ei."}],"Offertorium":[{"k":"ref","la":"Ps 90:4-5"},{"k":"text","la":"Scápulis suis obumbrábit tibi Dóminus, et sub pennis ejus sperábis: scuto circúmdabit te véritas ejus."}],"Secreta":[{"k":"text","la":"Sacrifícium quadragesimális inítii sollémniter immolámus, te, Dómine, deprecántes: ut, cum epulárum restrictióne carnálium, a noxiis quoque voluptátibus temperémus."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 90:4-5"},{"k":"text","la":"Scápulis suis obumbrábit tibi Dóminus, et sub pennis ejus sperábis: scuto circúmdabit te véritas ejus."}],"Postcommunio":[{"k":"text","la":"Tuis nos, Dómine, sacraménti libátio sancta restáuret: et a vetustáte purgátos, in mystérii salutáris fáciat transíre consórtium."},{"k":"macro","name":"Per Dominum"}]},"hr":{"a078b37dd9f6db0c":{"t":"Ps 90, 15-16, Ps 90, 1\n(Ps 90, 1-16) Zazvat će me i ja ću ga uslišiti; izbavit ću ga i proslaviti, dat ću mu da dugo živi. (Ps 90, 1) Tko stanuje pod okriljem Svevišnjega, prebivat će pod zaštitom Boga nebeskoga.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 90, 1-16) Zazvat će me i ja ću ga uslišiti; izbavit ću ga i proslaviti, dat ću mu da dugo živi."},"af8706bd228e714a":{"t":"<i>Pomolimo se</i>.\nBože, koji svake godine čistiš svoju Crkvu četrdesetdnevnim postom, podaj svojoj obitelj da izvršuje dobrim djelima ono što nastoji od tebe dobiti odricanjem.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"8b6ddce4e1bcfd21":{"t":"2 Kor 6, 1-10\nČitanje Poslanice bl. Pavla apostola Korinćanima. Braćo: opominjemo vas da ne primate uzalud Božje milosti. Jer on govori: »Uslišio sam te u pravo vrijeme i pomogao ti u dan spasenja.« Evo, sad je pravo vrijeme, sad je dan spasenja! – Nikomu ni u čemu ne davajmo sablazni da se ne bi kudila naša služba, nego se u svemu vladajmo kao Božje sluge: s mnogo strpljivosti u nevoljama, u tjeskobama, pod udarcima, u tamnicama, u bunama, u naporima, u bdjenjima, u postovima; čistoćom, znanjem, velikodušnošću, blagošću, Duhom Svetim, iskrenom ljubavlju, riječju istine, Božjom silom, oružjem pravde za napad i obranu; u slavi i sramoti, na zlu i dobru glasu. – Drže nas za zavodnike, a mi smo ljubitelji istine; za nepoznate, a poznaju nas; kao da umiremo, a mi evo živimo; za kažnjene, a ipak nismo predani smrti; za tužne, a mi smo uvijek veseli; za siromahe, a mi obogaćujemo mnoge; za ljude bez igdje ičega, a mi imamo sve."},"ff80dc06d93db49f":{"t":"Ps 90, 11-12\nSvojim je anđelima zapovjedio za tebe da te čuvaju na svim tvojim putovima. Oni će te nositi na rukama da ne udariš o kamen svojom nogom.\n\nPs 90, 1-7 i 11-16\nTko stanuje pod okriljem Svevišnjega prebivat će pod zaštitom Boga nebeskoga. Kazat će Gospodinu: Ti si mi zaštitnik i utočište, moj Bog u kojega se uzdam. Jer me je on izbavio od zamke lovaca i od oštre riječi. Svojim će te plećima zakloniti, pod njegovim ćeš krilima naći utočište. Kao štitom okružit će te njegova vjernost, nećeš se bojati noćnog straha, ni strijele koja leti danju, ni nezgode koja ide po mraku, ni nasrtaja neprijatelja usred dana. Kraj tebe će pasti tisuća i deset tisuća s tvoje desne, ali se tebi neće približiti, jer je svojim anđelima zapovjedio za tebe da te čuvaju na svim tvojim putovima. Na rukama će te nositi da ne udariš o kamen svojom nogom. Hodat ćeš po zmiji i poskoku i zgazit ćeš lava i zmaja. Jer se u mene uzdao, oslobodit ću ga. Zaklonit ću ga, jer je poznao moje ime. Zazvat će me i ja ću ga uslišiti. Bit ću uz njega u nevolji. Izbavit ću ga i proslaviti. Dat ću mu da dugo živi i pokazat ću mu svoje spasenje.","v":"∅ → deus"},"c60945759f5ef884":{"t":"Mt 4, 1-11\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme: Duh odvede Isusa u pustinju, da ga iskuša đavao. I kad je postio četrdeset dana i četrdeset noći, napokon ogladnje. Tada mu pristupi napasnik i reče: »Ako si Božji Sin, reci da ovo kamenje postane kruh.« On odgovori: »Pisano je: Ne živi čovjek samo o kruhu, nego o svakoj riječi koja izlazi iz Božjih usta.« – Zatim ga đavao odvede u sveti grad i postavi ga na vrh hrama i reče mu: »Ako si Božji Sin, baci se dolje, jer je pisano: Svojim je anđelima zapovjedio za tebe da te nose na svojim rukama, da ne udariš o kamen svojom nogom.« Isus mu reče: »Ali je također pisano: Ne kušaj Gospodina, svoga Boga.« – Još ga odvede đavao na vrlo visoku goru odakle mu pokaže sva kraljevstva svijeta i njihovu slavu pa mu reče: »Sve ću ti ovo dati, ako padneš ničice i meni se pokloniš.« Tada mu reče Isus: »Odlazi, sotono! Pisano je: Klanjaj se Gospodinu, svomu Bogu, njemu jedinom služi.« Tada ga ostavi đavao. I gle, došli su anđeli te mu služahu."},"9a4d95328b7ee0cc":{"t":"Ps 90, 4-5\nGospodin će te zakloniti svojim plećima i pod njegovim ćeš krilima naći utočište. Kao štitom okružit će te njegova vjernost."},"3d1031dd99c279f2":{"t":"Svečano ti, Gospodine, prinosimo žrtvu korizmenog početka i molimo te da se ustezanjem od tjelesne hrane uzdržimo i od štetnih naslada.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"8e0447f4695d07e4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi Gospodine, sveti Oče, svemogući vječni Bože: – ti tjelesnim postom suzbijaš opačine, uzdižeš dušu, daješ krepost i nagrade po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"fddf5b0ab9c158ce":{"t":"<i>Pomolimo se</i>.\nSveto žrtvovanje tvojeg otajstva, Gospodine, neka nas obnovi, da očišćeni od starih mana zavrijedimo dobiti dio u tajni spasenja.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
